<template><aside class="builder-panel widget-library" aria-label="Widget library"><header class="builder-panel__heading"><div><span>⌘</span><strong>Widget Library</strong></div><small>{{ activeTypes.size }} active</small></header><div class="library-search"><input v-model="search" type="search" placeholder="Search widgets…" aria-label="Search widgets"><button type="button" aria-label="Clear filters" @click="category='All'">⌁</button></div><div class="library-filters"><button v-for="item in categories" :key="item" type="button" :class="{active:category===item}" @click="category=item">{{ item }}</button></div><div class="library-items"><button v-for="item in filtered" :key="item.type" type="button" :class="{selected:selectedType===item.type,active:activeTypes.has(item.type)}" @click="choose(item)"><span class="library-icon">{{ item.icon }}</span><span><b>{{ label(item) }}</b><small>{{ description(item) }}</small><em>{{ normalizedCategory(item) }}</em></span><input type="checkbox" :checked="activeTypes.has(item.type)" :aria-label="`${activeTypes.has(item.type)?'Remove':'Add'} ${label(item)}`" @click.stop @change="$emit('toggle',item.type,$event.target.checked)"></button></div><aside class="library-tip"><strong>✦ Tip</strong><span>Check a widget to add it. Select active widgets here, on canvas, or in Layers.</span></aside></aside></template>
<script setup>import{computed,ref}from'vue';import{widgetDefinitions}from'../../widgets/registry/index.js';const props=defineProps({widgets:{type:Array,default:()=>[]},selectedId:String});const emit=defineEmits(['toggle','select']);const search=ref('');const category=ref('All');const categories=['All','Alerts','Chat','Goals','Events','Community','Accessibility','Creator','Other'];const categoryMap={Twitch:'Chat','Project Respawn':'Community',General:'Other',Partner:'Other'};const activeTypes=computed(()=>new Set(props.widgets.map(w=>w.type)));const selectedType=computed(()=>props.widgets.find(w=>w.id===props.selectedId)?.type||'');function normalizedCategory(item){if(['alerts','subscription-alert','raid-alert'].includes(item.type))return'Alerts';if(item.type==='tts')return'Accessibility';if(['goal','supporter-goal'].includes(item.type))return'Goals';if(item.type==='upcoming-event')return'Events';return categoryMap[item.category]||item.category}const filtered=computed(()=>widgetDefinitions.filter(item=>(category.value==='All'||normalizedCategory(item)===category.value)&&`${label(item)} ${description(item)}`.toLowerCase().includes(search.value.toLowerCase())));function label(item){return item.type==='twitch-chat'?'Unified Chat':item.type==='alerts'?'Follower Alert':item.displayName}function description(item){return{alerts:'Follower, sub, raid & more','twitch-chat':'Twitch, YouTube & Discord concept',tts:'TTS messages on stream',goal:'Follower, sub or community goal','upcoming-event':'Events and countdowns','webcam-frame':'Creator camera styling'}[item.type]||`${normalizedCategory(item)} overlay widget`}function choose(item){const widget=props.widgets.find(w=>w.type===item.type);if(widget)emit('select',widget.id);else emit('toggle',item.type,true)}</script>
